 function renderRanking(entries=[]){const rows=stackLeaders(entries),body=$('#st-ranking-body');body.replaceChildren();for(const[i,r]of rows.entries()){const tr=document.createElement('tr');for(const[col,value]of[format(r.score),r.name,format(r.floors)+'층',new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric'}).format(r.at)].entries()){const td=document.createElement('td');if(col===1&&i<3){const name=document.createElement('span'),icon=document.createElement('span'),label=document.createElement('span');name.className='st-rank-name';icon.className='st-trophy';icon.dataset.place=i+1;icon.setAttribute('role','img');icon.setAttribute('aria-label',['금트로피','은트로피','동트로피'][i]);icon.innerHTML=trophy;label.textContent=value;name.append(icon,label);td.append(name);}else td.textContent=value;tr.append(td);}body.append(tr);}$('#st-empty').hidden=rows.length>0;$('#st-empty').textContent='아직 등록된 기록이 없습니다.';}
